DROP TABLE IF EXISTS Status;
DROP TABLE IF EXISTS Information;

CREATE TABLE Information (
    id VARCHAR,
    name VARCHAR,
    lat REAL,
    lon REAL,
    capacity INT,
    PRIMARY KEY (id)
);

CREATE TABLE Status (
    id VARCHAR,
    is_installed INT,
    is_renting INT,
    is_returning INT,
    last_reported VARCHAR,
    num_bikes_available INT,
    num_bikes_available_ebike INT,
    num_bikes_available_mechanical INT,
    num_docks_available INT,
    FOREIGN KEY (id) REFERENCES Information(id)
);

